def transform(grid):
    h,w=len(grid),len(grid[0]); g=[row[:] for row in grid]
    border_rows=[r for r in range(h) if all(v==2 for v in g[r])]
    border_cols=[c for c in range(w) if all(g[r][c]==2 for r in range(h))]
    upward=bool(border_rows and border_rows[0]==0) or bool(border_cols and border_cols[0]==0)
    # assume horizontal border
    border=border_rows[0] if border_rows else (border_cols[0] if border_cols else None)
    coords={(r,c) for r in range(h) for c in range(w) if g[r][c] not in (0,2)}
    comps=[]
    while coords:
        seed=coords.pop(); color=g[seed[0]][seed[1]]; comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in coords and g[q[0]][q[1]]==color:
                    coords.remove(q); comp.add(q); stack.append(q)
        comps.append((color,comp))
    if border_rows:
        comps.sort(key=lambda x: min(r for r,c in x[1]) if upward else -max(r for r,c in x[1]))
        landed={(border,c) for c in range(w)}
        out=[[0]*w for _ in range(h)]
        out[border]=[2]*w
        d=-1 if upward else 1
        for color,comp in comps:
            cells=set(comp)
            while True:
                moved={(r+d,c) for r,c in cells}
                if any(r<0 or r>=h or (r,c) in landed for r,c in moved): break
                cells=moved
            for r,c in cells:
                out[r][c]=color; landed.add((r,c))
        return out
    return grid

